-- ---------------- Maine freshwater (2026 Maine Fishing Laws & Rules, general law) ----------------
 ('Brook trout (and splake, Arctic charr)', array['brook trout','splake','arctic char'], array['ME'], 6, null, 'total', false, '2 per day from South Zone lakes, 1 in rivers Aug 16 – Sep 30 (5 elsewhere)', false, null, null,
  'General law: 6″ minimum, 5 per day; only 2 from South Zone lakes and ponds; rivers and streams Aug 16 – Sep 30: lures or flies only, 1 brook trout. Rivers and streams are closed Oct 1 – Mar 31; North Zone lakes too. Many waters have special laws (look up the water).', 'https://www.maine.gov/ifw/docs/25-MDIFW-23-FISHING-LAWBOOK-2026.pdf', '2026-10-22', true),
 ('Brown trout', array['brown trout'], array['ME'], 14, null, 'total', false, '2 per day', false, null, null,
  'Lakes and ponds: 14″ minimum. Rivers and streams: 6″ minimum, 25″ maximum. Many waters have special laws.', 'https://www.maine.gov/ifw/docs/25-MDIFW-23-FISHING-LAWBOOK-2026.pdf', '2026-10-22', true),
 ('Rainbow trout', array['rainbow trout'], array['ME'], 12, null, 'total', false, '2 per day', false, null, null,
  'Lakes and ponds: 12″ minimum. Rivers and streams: 6″ minimum.', 'https://www.maine.gov/ifw/docs/25-MDIFW-23-FISHING-LAWBOOK-2026.pdf', '2026-10-22', true),
 ('Landlocked salmon', array['landlocked salmon'], array['ME'], 14, null, 'total', false, '2 per day (1 in rivers Aug 16 – Sep 30)', false, null, null,
  'Lakes and ponds: 14″ minimum. Rivers and streams: 14″ minimum and 25″ maximum (so a sea-run salmon is never kept by mistake).', 'https://www.maine.gov/ifw/docs/25-MDIFW-23-FISHING-LAWBOOK-2026.pdf', '2026-10-22', true),
 ('Sea-run Atlantic salmon', array['atlantic salmon','sea-run salmon'], array['ME'], null, null, 'total', false, 'Never keep', true, null, null,
  'Endangered: no fishing for them. Release any you catch at once without taking it out of the water.', 'https://www.maine.gov/ifw/docs/25-MDIFW-23-FISHING-LAWBOOK-2026.pdf', '2026-10-22', true),
 ('Lake trout (togue)', array['lake trout','togue','laker'], array['ME'], 18, null, 'total', false, '2 per day', false, null, null,
  'General law; many lakes have special laws.', 'https://www.maine.gov/ifw/docs/25-MDIFW-23-FISHING-LAWBOOK-2026.pdf', '2026-10-22', true),
 ('Black bass (largemouth, smallmouth)', array['largemouth','smallmouth','black bass'], array['ME'], null, 14, 'total', true, '2 per day in the South Zone (no limit in the North Zone)', false, null, null,
  'No minimum. Only 1 may be over 14″.', 'https://www.maine.gov/ifw/docs/25-MDIFW-23-FISHING-LAWBOOK-2026.pdf', '2026-10-22', true),
 ('Whitefish', array['lake whitefish','whitefish'], array['ME'], null, null, 'total', false, '3 per day', false, null, null,
  'No minimum.', 'https://www.maine.gov/ifw/docs/25-MDIFW-23-FISHING-LAWBOOK-2026.pdf', '2026-10-22', true),
 ('Redfin pickerel and sturgeon', array['redfin pickerel','sturgeon'], array['ME'], null, null, 'total', false, 'Never keep', true, null, null,
  'Redfin pickerel are endangered; sturgeon: no fishing permitted.', 'https://www.maine.gov/ifw/docs/25-MDIFW-23-FISHING-LAWBOOK-2026.pdf', '2026-10-22', true),
 ('American shad', array['american shad','white shad'], array['ME'], null, null, 'total', false, '2 per day', false, null, null,
  'No minimum. River herring: 25 per day, closed Thursday 6 am – Sunday 6 am.', 'https://www.maine.gov/ifw/docs/25-MDIFW-23-FISHING-LAWBOOK-2026.pdf', '2026-10-22', true),
 ('American eel', array['american eel'], array['ME'], 9, null, 'total', false, '25 per day', false, null, null,
