 ('Pollock', array['pollock'], array['ME'], 19, null, 'total', false, 'No daily limit', false, null, null,
  'Federal waters: 19″ minimum (the stricter size shown). Maine state waters: no size or bag limit.', 'https://www.maine.gov/dmr/sites/maine.gov.dmr/files/inline-files/2026_sportfish_regs_Gabrielle%20Page_0.pdf', '2026-10-22', true),
