-- ---------------- Michigan trout and salmon (2026 Michigan Fishing Regulations: Great Lakes p. 18-21, inland p. 42-43) ----------------
 ('Brook trout', array['brook trout'], array['MI'], 20, null, 'total', false, '1 per day on Lake Superior (5 trout and salmon elsewhere)', false, null, null,
  'Lake Superior (the stricter area): 20″, 1 per day; none may be kept near Isle Royale. Lakes Michigan, Huron, Erie: 10″. Inland streams not on the trout-type list: 7″; inland lakes not on the list: 8″. Listed trout lakes and streams (Types A–F, 1–4) have their own sizes and seasons (most typed streams: last Saturday in April – Sep 30).', 'https://www.michigan.gov/dnr/-/media/Project/Websites/dnr/Documents/LED/digests/2026-Michigan-Fishing-Regulations_web_accessible.pdf', '2026-10-22', true),
 ('Brown trout, rainbow trout (steelhead) and Atlantic salmon', array['brown trout','rainbow trout','steelhead','atlantic salmon'], array['MI'], 10, null, 'total', false, '5 trout and salmon per day, no more than 3 of one kind', false, null, null,
  'Great Lakes and their connecting rivers: 10″. Inland waters not on the trout-type list: 8″, 5 per day with no more than 3 that are 15″ or longer. Listed trout lakes and streams have their own sizes (up to 15″) and seasons.', 'https://www.michigan.gov/dnr/-/media/Project/Websites/dnr/Documents/LED/digests/2026-Michigan-Fishing-Regulations_web_accessible.pdf', '2026-10-22', true),
 ('Chinook, coho and pink salmon', array['chinook','king salmon','coho','silver salmon','pink salmon'], array['MI'], 10, null, 'total', false, '5 trout and salmon per day (up to 5 may be Chinook, coho or pink)', false, null, null,
  'Great Lakes: open all year. St. Marys River: 5 extra pink salmon from the last Saturday in April – Sep 30.', 'https://www.michigan.gov/dnr/-/media/Project/Websites/dnr/Documents/LED/digests/2026-Michigan-Fishing-Regulations_web_accessible.pdf', '2026-10-22', true),
 ('Lake trout and splake', array['lake trout','splake','laker','mackinaw'], array['MI'], 15, 34, 'total', true, '2 per day in parts of Lake Michigan (3 in most other areas)', false, '[["10-01","12-31"]]'::jsonb, null,
  'Great Lakes: 15″ minimum by unit. Lake Superior: only 1 over 34″; Stannard Rock and Big Reef: 1 per day. Northern Lake Huron (MH-1, MH-2) and northern Lake Michigan (MM-1 to MM-5) are closed Oct 1 – Dec 31 (the stricter dates shown); other units are open all year.', 'https://www.michigan.gov/dnr/-/media/Project/Websites/dnr/Documents/LED/digests/2026-Michigan-Fishing-Regulations_web_accessible.pdf', '2026-10-22', true),
-- ---------------- Wisconsin trout and salmon (Trout Fishing Regulations 2026-2027; Hook and Line Fishing Regulations 2026-2027, Great Lakes) ----------------
 ('Brook trout', array['brook trout'], array['WI'], 20, null, 'total', false, '1 per day on Lake Superior (5 trout in total on most inland streams)', false, null, null,
  'Lake Superior (the stricter area): 20″, 1 per day. Lake Superior streams not listed: 8″. Inland streams: Green waters 5 of any size, Yellow waters 3 over 8″; Red waters have their own rules. Inland streams are open the first Saturday in April – Oct 15 (catch and release Jan – early April on listed streams).', 'https://widnr.widen.net/s/glhqr9znsp/fishingregselectronic2627', '2026-10-22', true),
 ('Brown trout and splake', array['brown trout','splake'], array['WI'], 15, null, 'total', false, '3 per day on Yellow inland waters (5 trout and salmon in total elsewhere)', false, null, null,
  'Lake Superior: 15″. Lake Michigan and its tributaries: 10″. Inland streams: Green waters 5 of any size, Yellow waters 3 over 8″.', 'https://widnr.widen.net/s/glhqr9znsp/fishingregselectronic2627', '2026-10-22', true),
 ('Rainbow trout (steelhead)', array['rainbow trout','steelhead'], array['WI'], 26, null, 'total', false, '1 per day on Lake Superior and its streams (5 trout and salmon in total on Lake Michigan)', false, null, null,
  'Lake Superior and its streams (the stricter area): 26″, 1 per day. Lake Michigan and its tributaries: 10″. Inland streams: Green waters any size, Yellow waters over 8″.', 'https://widnr.widen.net/s/glhqr9znsp/fishingregselectronic2627', '2026-10-22', true),
 ('Salmon (Chinook, coho, pink, Atlantic)', array['chinook','king salmon','coho','silver salmon','pink salmon','atlantic salmon'], array['WI'], 10, null, 'total', false, '5 trout and salmon per day (together)', false, null, null,
  'Lake Michigan and its tributaries: 10″. Lake Superior: 5 per day, no minimum; Lake Superior streams: 12″.', 'https://widnr.widen.net/s/glhqr9znsp/fishingregselectronic2627', '2026-10-22', true),
 ('Lake trout', array['lake trout','laker','mackinaw'], array['WI'], 15, 25, 'total', true, '2 per day east of Bark Point on Lake Superior (3 west); 5 trout and salmon on Lake Michigan', false, '[["10-01","11-30"]]'::jsonb, null,
  'Lake Superior: 15″, only 1 over 25″, closed Oct 1 – Nov 30. Lake Michigan: 10″, open all year (no fishing on the Mid Lake Reef Complex). Inland lakes: 17″ or 30″ on listed lakes.', 'https://widnr.widen.net/s/glhqr9znsp/fishingregselectronic2627', '2026-10-22', true),
-- ---------------- Indiana trout and salmon (2026 Indiana Fishing Regulation Guide: inland trout p. 20, Lake Michigan p. 22) ----------------
 ('Trout (rainbow, brook) and steelhead', array['rainbow trout','brook trout','steelhead'], array['IN'], 14, null, 'total', false, '5 per day', false, null, null,
  'Lake Michigan and its tributaries: 14″ (the stricter size shown), 5 trout and salmon in total. Inland streams: 7″; inland lakes: no minimum. Inland streams are catch and release Jan 1 – Apr 14, and some stocked streams are closed Apr 15 – the last Saturday in April. A trout/salmon stamp is needed.', 'https://www.eregulations.com/assets/docs/guides/26INFW_LR.pdf', '2026-10-22', true),
 ('Brown trout', array['brown trout'], array['IN'], 14, null, 'total', false, '1 per day on inland waters (5 trout and salmon on Lake Michigan)', false, null, null,
  'Lake Michigan and its tributaries: 14″. Inland: 7″ in streams, no minimum in lakes, and only 1 brown trout a day; 18″ at Oliver, Olin and Martin lakes and the Brookville Lake tailwater.', 'https://www.eregulations.com/assets/docs/guides/26INFW_LR.pdf', '2026-10-22', true),
 ('Salmon (Chinook, coho, pink, Atlantic)', array['chinook','king salmon','coho','silver salmon','pink salmon','atlantic salmon'], array['IN'], 14, null, 'total', false, '5 trout and salmon per day', false, null, null,
  'Lake Michigan and its tributaries. Fish in the tributaries must be hooked in the mouth.', 'https://www.eregulations.com/assets/docs/guides/26INFW_LR.pdf', '2026-10-22', true),
 ('Lake trout', array['lake trout','laker'], array['IN'], 14, null, 'total', false, '3 per day (inside the 5 trout and salmon)', false, null, null,
  'Lake Michigan.', 'https://www.eregulations.com/assets/docs/guides/26INFW_LR.pdf', '2026-10-22', true);
